const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-0.819876, 53.083908);
  const roi = point.buffer(5000); // 5 km radius

  const date2024_start = '2024-01-01';
  const date2024_end = '2024-01-07'; // A few days window for 2024-01-04

  const date2022_start = '2022-01-01';
  const date2022_end = '2022-01-08'; // A few days window for 2022-01-05

  // S1 processing function
  const processS1 = (image) => {
    // Select VV band and convert to dB
    const vv = image.select('VV').focal_median(30, 'square', 'pixels').unitScale(0, 1).multiply(255).uint8(); // speckle filter, then scale to 0-255 for better thresholding

    // Apply a threshold to detect water. This threshold often needs tuning
    // -18 dB is a common value, but scaling to 0-255 means we need to find an equivalent.
    // Let's use Otsu thresholding or a fixed one after scaling to 0-255 if dB is complex.
    // A simple approach: assume water is darker. A threshold around 50-70 after scaling to 0-255 often works for water.
    const waterMask = vv.lt(60).rename('water_mask'); // Lower values after scaling indicate water (darker)

    // Calculate pixel area and multiply by the water mask to get water area
    const waterAreaSqMeters = waterMask.multiply(ee.Image.pixelArea()).divide(1e6); // Convert to km^2

    return waterAreaSqMeters.set('system:time_start', image.get('system:time_start'));
  };

  // Function to get image collection and calculate water area
  const getWaterArea = async (startDate, endDate, roiName) => {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD_FLOAT')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .map(processS1);

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No Sentinel-1 images found for ${roiName} between ${startDate} and ${endDate}.`);
      return null; // Indicates C1
    }

    // Take the median of the water area images to represent the period
    const waterAreaImage = collection.reduce(ee.Reducer.median());

    // Reduce region to get the total water area in km^2
    const totalWaterArea = await waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi,
      scale: 10, // S1 resolution is 10m
      maxPixels: 1e9
    }).get('water_mask_median').getInfo();

    return {
      area: totalWaterArea,
      numImages: collectionSize
    };
  };

  let waterStats2024, waterStats2022;

  try {
    waterStats2024 = await getWaterArea(date2024_start, date2024_end, '2024');
    waterStats2022 = await getWaterArea(date2022_start, date2022_end, '2022');
  } catch (e) {
    console.log("Error during data acquisition or processing:", e);
    console.log("D"); // Generic error or syntax issue
    return;
  }

  // Check for C1 (Empty Collection)
  if (waterStats2024 === null || waterStats2022 === null) {
    console.log("C1");
    return;
  }

  const waterArea2024 = waterStats2024.area;
  const waterArea2022 = waterStats2022.area;

  // Check for C3 (Calculation Failure - None, NaN)
  if (waterArea2024 === null || isNaN(waterArea2024) || waterArea2022 === null || isNaN(waterArea2022)) {
    console.log("Calculation resulted in None or NaN.");
    console.log("C3");
    return;
  }

  // Check for C2 (No Valid Pixels - This interpretation means 0 water detected)
  // If `reduceRegion` returned a number (even 0), it means it had valid pixels.
  // A value of 0 for water extent is a valid result, not an error.
  // C2 would imply *no* pixels in the ROI for *any* band.
  // Since S1 covers the entire area, we assume there are always pixels.
  // If `water_mask_median` was 0, it means 0 water, which is a valid answer.

  console.log(`2024 Images: ${waterStats2024.numImages}, Water Extent (km²): ${waterArea2024 !== null ? waterArea2024.toFixed(2) : 'N/A'}`);
  console.log(`2022 Images: ${waterStats2022.numImages}, Water Extent (km²): ${waterArea2022 !== null ? waterArea2022.toFixed(2) : 'N/A'}`);

  // 5. Validation & Final Answer
  if (waterArea2024 > waterArea2022) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
